import { type Dialog, type Pagination, type Sort, type TabActionDialog } from "@dashboard/types";
import { stringifyQs } from "@dashboard/utils/urls";
import urlJoin from "url-join";

export enum DiscountListUrlSortField {
  name = "name",
  endDate = "endDate",
  startDate = "startDate",
}

const discountSection = "/discounts/sales";

export const discountSalesListPath = discountSection;

export type DiscountListUrlDialog = TabActionDialog;

type DiscountListUrlSort = Sort<DiscountListUrlSortField>;

export type DiscountListUrlQueryParams = Dialog<DiscountListUrlDialog> &
  Pagination &
  DiscountListUrlSort & {
    query?: string;
  };

type DiscountUrlDialog = "remove";
export type DiscountUrlQueryParams = Dialog<DiscountUrlDialog>;

export const discountListUrl = (params?: DiscountListUrlQueryParams) =>
  discountSection + "?" + stringifyQs(params);

export const discountUrl = (id: string, params?: DiscountListUrlQueryParams) =>
  urlJoin(discountSection, id) + "?" + stringifyQs(params);

export const discountAddUrl = () => urlJoin(discountSection, "add");
import { ChannelDisplay } from "@dashboard/components/Channel/Channel";
import { formatMoney } from "@dashboard/components/Money";
import { formatPercantage } from "@dashboard/components/Percent/utils";
import { type Rule } from "@dashboard/discounts/models/Rule";
import { RewardTypeEnum, RewardValueTypeEnum } from "@dashboard/graphql";
import useLocale from "@dashboard/hooks/useLocale";
import { type CommonError } from "@dashboard/utils/errors/common";
import { Box, Text } from "@saleor/macaw-ui-next";
import { useIntl } from "react-intl";

import { useDiscountRulesContext } from "../../context/consumer";
import { messages } from "../../messages";
import { getCurencySymbol } from "../../utils";
import { Placeholder } from "../Placeholder/Placeholder";
import { RuleActions } from "./components/RuleActions/RuleActions";
import { RuleLabel } from "./components/RuleLabel/RuleLabel";
import { RuleListContainer } from "./components/RuleListContainer/RuleListContainer";
import { RuleListLoading } from "./components/RuleListLoading/RuleListLoading";
import { RuleSummary } from "./components/RuleSummary/RuleSummary";
import { RuleWrapper } from "./components/RuleWrapper/RuleWrapper";

interface RulesListProps<ErrorCode> {
  rules: Rule[];
  disabled?: boolean;
  errors: Array<CommonError<ErrorCode> & { index?: number }>;
  loading?: boolean;
  onRuleDelete: (index: number) => void;
  onRuleEdit: (index: number) => void;
}

export const RulesList = <ErrorCode,>({
  rules,
  errors,
  onRuleEdit,
  onRuleDelete,
  loading,
}: RulesListProps<ErrorCode>) => {
  const intl = useIntl();
  const { channels } = useDiscountRulesContext();

  if (loading) {
    return <RuleListLoading />;
  }

  if (rules.length === 0) {
    return <Placeholder />;
  }

  return (
    <RuleListContainer>
      {rules.map((rule, index) => {
        const hasError = errors.some(error => error.index === index);
        const currencySymbol = getCurencySymbol(rule.channel, channels);
        const channelData = rule.channel ? channels.find(c => c.id === rule.channel?.value) : null;

        return (
          <RuleWrapper key={rule.id || index} hasError={hasError}>
            <Box display="flex" flexDirection="column" gap={3} __minWidth={0}>
              <Box
                display="flex"
                justifyContent="space-between"
                alignItems="flex-start"
                gap={3}
                flexWrap="wrap"
                __minWidth={0}
              >
                <Box
                  display="flex"
                  flexDirection="column"
                  gap={1}
                  __minWidth={0}
                  __flex="1 1 12rem"
                >
                  <RuleLabel ruleName={rule.name} />

                  {rule.channel && (
                    <ChannelDisplay
                      channel={{
                        id: rule.channel.value,
                        name: rule.channel.label,
